<script setup>
import AppButton from '@/components/ui/AppButton.vue'
import MoreMenu from '@/components/ui/MoreMenu.vue'
import PayRunNextStep from '@/components/payroll/PayRunNextStep.vue'
import { formatWorkDate } from '@/utils/payrollPeriods'
defineProps({run:Object,total:Number,count:Number,agencies:Array,issues:Array,warnings:Array,downloads:Array,busy:Boolean,enabled:Boolean,practice:Boolean})
defineEmits(['approve','payment','finish','resolve','review','payslips'])
const money=value=>`₱${Number(value||0).toLocaleString('en-PH',{minimumFractionDigits:2,maximumFractionDigits:2})}`
const stamp=value=>value?new Date(value).toLocaleString('en-PH',{timeZone:'Asia/Manila',dateStyle:'medium',timeStyle:'short'}):''
const actor=(run,action)=>[...(run.events||[])].reverse().find(event=>event.action===action)?.actor_name || ''
</script>

<template>
  <section class="space-y-4">
    <div class="rounded-xl border border-gray-800 bg-gray-900 p-5"><header class="flex items-center justify-between gap-3"><h2 class="font-semibold">Finalize payroll</h2><MoreMenu label="Download" :items="downloads||[]" /></header><p class="mt-5 text-sm text-gray-500">Net pay to {{count}} employees</p><p class="mt-1 text-3xl font-semibold text-emerald-300">{{money(total)}}</p><button class="mt-3 text-sm text-primary-300 underline" @click="$emit('review')">View pay breakdown</button><details v-if="agencies?.length" class="mt-5 border-t border-gray-800 pt-3"><summary class="cursor-pointer text-sm font-medium">Agency remittances · {{money(agencies.reduce((sum,item)=>sum+item.amount,0))}}</summary><p class="mt-2 text-xs text-gray-500">Employee and employer shares, paid separately to each agency.</p><dl class="mt-2 space-y-1 text-sm"><div v-for="item in agencies" :key="item.name" class="flex justify-between gap-3"><dt>{{item.name}}</dt><dd>{{money(item.amount)}}</dd></div></dl></details></div>
    <section v-if="run.status==='draft' && issues?.length" class="rounded-xl border p-4" style="border-color:var(--warning-border);background:var(--warning-bg);color:var(--warning-text)" role="status" aria-label="Payroll blockers"><h3 class="text-sm font-semibold">{{issues.length}} {{issues.length===1?'thing':'things'}} to resolve</h3><ul class="mt-3 space-y-3"><li v-for="issue in issues" :key="issue.key" class="flex flex-wrap items-center justify-between gap-3 text-sm"><span>{{issue.text}}</span><AppButton variant="secondary" size="sm" @click="$emit('resolve',issue)">{{issue.actionLabel}}</AppButton></li></ul></section>
    <details v-if="run.status==='draft' && warnings?.length" class="rounded-lg border border-gray-800 px-4 py-3 text-sm"><summary class="cursor-pointer">Additional checks ({{warnings.length}})</summary><ul class="mt-3 space-y-3"><li v-for="warning in warnings" :key="warning.text"><p>{{warning.text}}</p><p class="mt-1 text-xs text-gray-500">{{warning.detail}}</p></li></ul></details>
    <details v-if="run.approved_at" class="rounded-lg border border-gray-800 px-4 py-3 text-sm"><summary class="cursor-pointer">Completed actions</summary><ol class="mt-3 space-y-2 text-xs text-gray-500"><li>Approved {{stamp(run.approved_at)}}<span v-if="actor(run,'approved')"> · {{actor(run,'approved')}}</span></li><li v-if="run.payment">Payment {{formatWorkDate(run.payment.paid_on)}} · {{run.payment.reference}}<span v-if="actor(run,practice?'practice_payment_recorded':'payment_recorded')"> · {{actor(run,practice?'practice_payment_recorded':'payment_recorded')}}</span></li><li v-if="run.locked_at">Finished {{stamp(run.locked_at)}}<span v-if="actor(run,'locked')"> · {{actor(run,'locked')}}</span></li></ol></details>
    <PayRunNextStep v-if="run.status==='draft' && !issues?.length" title="Approve checked amounts" :detail="enabled?'Approval freezes this payroll.':'Real payroll finalization is currently disabled.'"><AppButton :loading="busy" :disabled="!enabled" @click="$emit('approve')">{{practice?'Approve practice payroll':'Approve payroll'}}</AppButton></PayRunNextStep>
    <PayRunNextStep v-else-if="run.status==='approved' && !run.payment" title="Record payment" detail="After the bank transfer, record its date and reference. The app does not move money."><AppButton :loading="busy" @click="$emit('payment')">Record payment</AppButton></PayRunNextStep>
    <PayRunNextStep v-else-if="run.status==='approved'" title="Ready to finish" :detail="practice?'Closes this practice run. You choose who gets a test payslip next.':'Closes this paid payroll and makes payslips available in My payslips. Email is optional.'"><AppButton :loading="busy" @click="$emit('finish')">{{practice?'Finish practice & open payslips':'Finish payroll & open payslips'}}</AppButton></PayRunNextStep>
    <PayRunNextStep v-else-if="run.status==='locked'" title="Payroll complete" tone="done"><AppButton @click="$emit('payslips')">Open payslips</AppButton></PayRunNextStep>
  </section>
</template>
